    'matchReasonExperiencedMatch': "அனுபவம் வாய்ந்த பொருத்தம் ({score}%) - {exp} ஆண்டுகள் அனுபவம், {time} மணிக்கு பிறகு கிடைக்கும்.",
    'matchReasonAffordableMatch': "சிக்கனமான பொருத்தம் ({score}%) - மலிவு விலை (₹{min} - ₹{max}) மற்றும் உடனடியாக கிடைக்கும்.",
